feito = 0
for n, fala in NOVO.items():
    ln = L[n - 1]
    assert re.match(r"\|\s*\d+:\d+", ln), (n, ln[:60])
    c = ln.strip()[2:-2].split(" | ")
    assert len(c) == 3, (n, len(c))
    c[2] = fala
    L[n - 1] = "| " + " | ".join(c) + " |"
    feito += 1
open(p, "w", encoding="utf-8").write("\n".join(L))
print("células reescritas:", feito)
